// Transient action messages live in the top layer, outside the widget's layout.
// Keep the original node/role so the component still owns its accessible feedback.
const messages = new WeakMap();
let active = null;
let timer = null;
let listening = false;

function dismiss() {
  if (!active) return;
  try { active.hidePopover?.(); } catch (_) { /* already closed or disconnected */ }
  active.hidden = true;
  active = null;
  clearTimeout(timer);
  timer = null;
}

function listen() {
  if (listening || !globalThis.document?.addEventListener) return;
  listening = true;
  for (const event of ['mobile-pager:change', 'desktop-info:change']) {
    document.addEventListener(event, dismiss);
  }
  document.addEventListener('keydown', event => {
    if (event.key !== 'Escape' || !active || !active.matches?.(':popover-open')) return;
    event.preventDefault();
    event.stopPropagation();
    dismiss();
  }, true);
  // Closing a popup must also retire feedback from its form.
  for (const event of ['close', 'app:panel-close']) {
    document.addEventListener(event, e => {
      if (active && e.target?.contains?.(active)) dismiss();
    }, true);
  }
}

export function setActionFeedback(node, message) {
  if (!node) return;
  const text = String(message || '');
  // Store refreshes must not reopen a dismissed message or restart its timeout.
  if (text && messages.get(node) === text) return;
  messages.set(node, text);
  if (active === node) dismiss();
  node.textContent = text;
  node.hidden = !text;
  if (!text) return;
  node.classList?.add('action-feedback');
  node.setAttribute?.('popover', 'auto');
  if (!node.isConnected) return;
  if (node.parentElement?.closest('[hidden]')) {
    node.hidden = true;
    return;
  }
  dismiss();
  listen();
  active = node;
  try { node.showPopover?.(); } catch (_) { /* fixed-position fallback */ }
  timer = setTimeout(dismiss, 10_000);
  timer?.unref?.();
}
